from __future__ import annotations

from minidb.types import KEYWORDS, OPERATORS, SQLSyntaxError, Token, TokenType

__all__ = [
    "tokenize",
    "is_identifier_start",
    "is_identifier_char",
    "read_string_literal",
]

def is_identifier_start(ch: str) -> bool:
    """Return True if ``ch`` may begin an identifier or keyword: an ASCII
    letter or underscore."""
    return ch.isascii() and (ch.isalpha() or ch == '_')

def is_identifier_char(ch: str) -> bool:
    """Return True if ``ch`` may continue an identifier or keyword: an ASCII
    letter, ASCII digit, or underscore."""
    return ch.isascii() and (ch.isalnum() or ch == '_')

def read_string_literal(sql: str, start: int) -> tuple[str, int]:
    """Read a single-quoted string literal beginning at ``sql[start]``
    (which must be ``'``).

    Returns ``(contents, end)`` where ``contents`` has ``''`` unescaped to
    ``'`` and ``end`` is the index just past the closing quote.

    Raises:
        SQLSyntaxError: if the literal is not terminated.
    """
    contents = []
    i = start + 1
    while i < len(sql):
        if sql[i] == "'":
            if i + 1 < len(sql) and sql[i + 1] == "'":
                contents.append("'")
                i += 2
            else:
                return ''.join(contents), i + 1
        else:
            contents.append(sql[i])
            i += 1
    raise SQLSyntaxError("unterminated string literal")

def tokenize(sql: str) -> list[Token]:
    """Convert ``sql`` into tokens, always ending with one EOF token.

    Raises:
        SQLSyntaxError: on an unterminated string or an unknown character.
    """
    tokens = []
    i = 0
    while i < len(sql):
        ch = sql[i]
        position = i
        if ch.isspace():
            i += 1
            continue
        elif is_identifier_start(ch):
            j = i + 1
            while j < len(sql) and is_identifier_char(sql[j]):
                j += 1
            word = sql[i:j]
            if word.upper() in KEYWORDS:
                tokens.append(Token(TokenType.KEYWORD, word.upper(), position))
            else:
                tokens.append(Token(TokenType.IDENTIFIER, word.lower(), position))
            i = j
        elif ch.isdigit():
            j = i + 1
            while j < len(sql) and sql[j].isdigit():
                j += 1
            tokens.append(Token(TokenType.INTEGER, sql[i:j], position))
            i = j
        elif ch == "'":
            string_value, i = read_string_literal(sql, i)
            tokens.append(Token(TokenType.STRING, string_value, position))
        elif any(sql.startswith(op, i) for op in OPERATORS):
            for op in OPERATORS:
                if sql.startswith(op, i):
                    tokens.append(Token(TokenType.OPERATOR, op, position))
                    i += len(op)
                    break
        else:
            raise SQLSyntaxError(f"unknown character: {ch}")
    tokens.append(Token(TokenType.EOF, "", len(sql)))
    return tokens

